<div class="eyebrow">FoxNetwork Admin</div><h1>Store management.</h1><div class="muted">Stage 4 product controls. Full provisioning arrives in Stage 5.</div><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif?><section class="card admin-products"><div class="cardhead"><b>PRODUCTS</b><a class="btn" href="/store.php">View Store</a></div><?php foreach($products as $p):?><div class="admin-product-row"><div><b><?=e($p['name'])?></b><div class="muted small"><?=e($p['category_name'])?> · <?=e((string)($p['ram_mb']/1024))?> GB RAM · <?=e($p['cpu_percent'])?>% CPU</div></div><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="price"><input type="hidden" name="id" value="<?=e($p['id'])?>"><span>€</span><input name="price" type="number" step="0.01" min="0" value="<?=e($p['price_monthly'])?>"><button class="btn">Save</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=e($p['id'])?>"><button class="btn <?=((int)$p['active']?'':'primary')?>"><?=((int)$p['active']?'Disable':'Enable')?></button></form></div><?php endforeach?></section></div></main></div></body></html>